import{_ as a,o as s,c as n,a5 as d}from"./chunks/framework.B5tqjWbr.js";const u=JSON.parse('{"title":"SYS-05 功能安全：电控系统的生命线 - 检验题目","description":"","frontmatter":{"date":"2026-06-08T00:00:00.000Z","section":"电机控制","chapter":"advanced","chapterTitle":"进阶专题","chapterOrder":30,"category":"进阶专题","source":"motor","visibility":"public","title":"SYS-05 功能安全：电控系统的生命线 - 检验题目","tags":["motor-control"],"status":"learning","summary":"**模块编号：** SYS-05 **题目数量：** 13题 **题型分布：** 概念理解8题（选择题）+ HARA分析2题 + FMEA表格2题 + 安全状态设计1题 **难度分布：** 基础4题 / 进阶5题 / 综合4题","navGroup":"实践与验证","navGroupOrder":40},"headers":[],"relativePath":"content/motor/advanced/system-methodology/SYS-05-assessment.md","filePath":"content/motor/advanced/system-methodology/SYS-05-assessment.md","lastUpdated":null}'),r={name:"content/motor/advanced/system-methodology/SYS-05-assessment.md"};function l(o,t,p,i,e,h){return s(),n("div",null,[...t[0]||(t[0]=[d(`<h1 id="sys-05-功能安全-电控系统的生命线-检验题目" tabindex="-1">SYS-05 功能安全：电控系统的生命线 - 检验题目 <a class="header-anchor" href="#sys-05-功能安全-电控系统的生命线-检验题目" aria-label="Permalink to &quot;SYS-05 功能安全：电控系统的生命线 - 检验题目&quot;">​</a></h1><p><strong>模块编号：</strong> SYS-05 <strong>题目数量：</strong> 13题 <strong>题型分布：</strong> 概念理解8题（选择题）+ HARA分析2题 + FMEA表格2题 + 安全状态设计1题 <strong>难度分布：</strong> 基础4题 / 进阶5题 / 综合4题</p><hr><h2 id="第一部分-概念理解-单项选择题-a-b-c-d" tabindex="-1">第一部分：概念理解（单项选择题，A/B/C/D） <a class="header-anchor" href="#第一部分-概念理解-单项选择题-a-b-c-d" aria-label="Permalink to &quot;第一部分：概念理解（单项选择题，A/B/C/D）&quot;">​</a></h2><h3 id="第1题-功能安全的本质" tabindex="-1">第1题：功能安全的本质 <a class="header-anchor" href="#第1题-功能安全的本质" aria-label="Permalink to &quot;第1题：功能安全的本质&quot;">​</a></h3><p><strong>题目：</strong> 关于功能安全的本质，以下理解最准确的是？</p><p>A. 功能安全就是给系统加保护电路和看门狗</p><p>B. 功能安全是一套系统化的工程方法论，核心是证明保护措施足够</p><p>C. 功能安全就是通过安全认证拿到证书</p><p>D. 功能安全就是按照ISO 26262写文档</p><p><strong>正确答案：</strong> B</p><p><strong>详细解析：</strong></p><p>功能安全的本质不是&quot;加保护&quot;，而是&quot;证明保护足够&quot;。这要求工程师从定性思维转变为定量思维——不仅要设计保护措施，还要量化诊断覆盖率、计算硬件度量、验证残余风险可接受。</p><ul><li><strong>选项A：</strong> &quot;加保护&quot;只是手段，不是目的。加了保护但无法证明其充分性，在安全审计面前毫无意义。</li><li><strong>选项B：</strong> 正确。功能安全是一套从危害分析到安全确认的完整方法论，每一步都有标准可依、有数据可查。</li><li><strong>选项C：</strong> 认证是结果，不是目的。为了认证而认证，往往导致文档与实现脱节。</li><li><strong>选项D：</strong> ISO 26262是方法论框架，不是&quot;写文档&quot;。文档只是证据载体，核心是工程实践。</li></ul><hr><h3 id="第2题-asil等级的决定因素" tabindex="-1">第2题：ASIL等级的决定因素 <a class="header-anchor" href="#第2题-asil等级的决定因素" aria-label="Permalink to &quot;第2题：ASIL等级的决定因素&quot;">​</a></h3><p><strong>题目：</strong> 同一个电机控制器，用在车载空调风机上评估为QM，用在电动汽车驱动系统上评估为ASIL-D。这说明ASIL等级由什么决定？</p><p>A. 由产品的技术复杂度决定</p><p>B. 由危害场景的严重度、暴露率和可控性决定</p><p>C. 由MCU的性能和冗余设计决定</p><p>D. 由客户的预算和安全投入决定</p><p><strong>正确答案：</strong> B</p><p><strong>详细解析：</strong></p><p>ASIL等级由HARA分析确定，HARA的三个维度是严重度(S)、暴露率(E)、可控性(C)。同一个产品在不同应用场景下，这三个维度可能完全不同。</p><ul><li><strong>选项A：</strong> 技术复杂度与ASIL等级无直接关系。一个简单的刹车开关可以是ASIL-D，一个复杂的娱乐系统可能只是QM。</li><li><strong>选项B：</strong> 正确。风机失控最多吹风不舒服（S1, C0→QM），驱动电机失控可导致致命事故（S3, E4, C3→ASIL-D）。</li><li><strong>选项C：</strong> MCU选型是ASIL等级确定后的设计决策，不是ASIL等级的决定因素。</li><li><strong>选项D：</strong> 安全等级不能因预算不足而降低。如果成本无法满足ASIL要求，应重新评估系统架构。</li></ul><hr><h3 id="第3题-过流保护的诊断覆盖率" tabindex="-1">第3题：过流保护的诊断覆盖率 <a class="header-anchor" href="#第3题-过流保护的诊断覆盖率" aria-label="Permalink to &quot;第3题：过流保护的诊断覆盖率&quot;">​</a></h3><p><strong>题目：</strong> 某电机控制器仅使用软件过流检测（ADC采样+阈值比较+延时确认），其诊断覆盖率约为90%。客户要求ASIL-B（SPFM≥97%），以下改进方案最有效的是？</p><p>A. 增加软件滤波，降低误检率</p><p>B. 增加硬件比较器直接封锁PWM，与软件检测形成双冗余</p><p>C. 降低过流阈值，提高灵敏度</p><p>D. 增加过流检测的延时确认时间</p><p><strong>正确答案：</strong> B</p><p><strong>详细解析：</strong></p><p>诊断覆盖率(DC)衡量的是&quot;故障发生时能被检测到的概率&quot;。提高DC需要增加检测手段的覆盖面，而非调整已有手段的参数。</p><ul><li><strong>选项A：</strong> 降低误检率提高的是&quot;检测准确性&quot;，不是诊断覆盖率。误检率和漏检率是两个概念——DC关注的是漏检率。</li><li><strong>选项B：</strong> 正确。硬件比较器能检测软件无法检测的故障（如ADC失效、MCU程序跑飞导致软件检测不执行），两者组合DC可达97%以上。硬件比较器覆盖的故障模式与软件检测互补。</li><li><strong>选项C：</strong> 降低阈值提高灵敏度，但可能增加误检率，且不增加对&quot;检测手段本身失效&quot;的覆盖。</li><li><strong>选项D：</strong> 增加延时确认反而降低了响应速度，且不提高DC。</li></ul><hr><h3 id="第4题-安全状态设计" tabindex="-1">第4题：安全状态设计 <a class="header-anchor" href="#第4题-安全状态设计" aria-label="Permalink to &quot;第4题：安全状态设计&quot;">​</a></h3><p><strong>题目：</strong> 电动汽车驱动电机在行驶中发生非预期加速故障，以下安全状态序列最合理的是？</p><p>A. 立即关闭PWM→电机高阻态→车辆自由滑行停止</p><p>B. 立即施加制动转矩→减速至安全速度→关闭PWM→高阻态</p><p>C. 立即切断整车电源→所有系统停止</p><p>D. 限制电机最大转矩→继续行驶→请求驾驶员停车</p><p><strong>正确答案：</strong> B</p><p><strong>详细解析：</strong></p><p>安全状态设计必须考虑&quot;从故障到安全&quot;的过渡过程，而非简单地&quot;关机了事&quot;。</p><ul><li><strong>选项A：</strong> 直接关PWM（高阻态）意味着电机失去所有转矩，但车辆仍在高速运动。在高速下自由滑行，制动距离长，且可能追尾。这不是&quot;安全状态&quot;，而是&quot;放弃控制&quot;。</li><li><strong>选项B：</strong> 正确。先利用电机本身的制动能力（施加反向电流）快速减速，待速度降到安全范围后再关PWM。这充分利用了电机的主动制动能力，是最安全的过渡方案。</li><li><strong>选项C：</strong> 切断整车电源会导致转向助力、刹车助力同时丧失，反而更危险。安全状态应保持辅助系统运行。</li><li><strong>选项D：</strong> 非预期加速时继续行驶不可接受——FTTI要求在100-200ms内进入安全状态。</li></ul><hr><h3 id="第5题-ftti的理解" tabindex="-1">第5题：FTTI的理解 <a class="header-anchor" href="#第5题-ftti的理解" aria-label="Permalink to &quot;第5题：FTTI的理解&quot;">​</a></h3><p><strong>题目：</strong> 某电机控制器的过流保护FTTI为50μs，以下说法正确的是？</p><p>A. 从过流发生到软件检测到故障的时间不超过50μs</p><p>B. 从过流发生到系统进入安全状态的总时间不超过50μs</p><p>C. 从过流发生到PWM被封锁的时间不超过50μs</p><p>D. 看门狗的超时时间设置为50μs</p><p><strong>正确答案：</strong> B</p><p><strong>详细解析：</strong></p><p>FTTI（Fault Tolerant Time Interval）是从故障发生到系统必须进入安全状态的最大允许时间。它是一个端到端的时间约束，包括检测时间+响应时间+执行时间。</p><ul><li><strong>选项A：</strong> 检测时间只是FTTI的一部分，还需要加上响应和执行时间。</li><li><strong>选项B：</strong> 正确。FTTI是端到端约束：故障发生→检测→判断→执行安全状态，全流程必须在50μs内完成。对于过流保护，这意味着必须用硬件比较器直接封锁PWM（软件无法在50μs内完成全流程）。</li><li><strong>选项C：</strong> PWM封锁是安全状态的执行动作，但FTTI是从故障发生开始计算的完整时间。</li><li><strong>选项D：</strong> 看门狗超时时间通常远大于FTTI（ms级vs μs级），两者是不同的概念。</li></ul><hr><h3 id="第6题-双核锁步" tabindex="-1">第6题：双核锁步 <a class="header-anchor" href="#第6题-双核锁步" aria-label="Permalink to &quot;第6题：双核锁步&quot;">​</a></h3><p><strong>题目：</strong> 关于双核锁步MCU，以下说法错误的是？</p><p>A. 两个核执行相同的指令流，每个时钟周期比较输出</p><p>B. 双核锁步可以检测CPU内部寄存器的单点故障</p><p>C. 双核锁步MCU的计算能力是普通MCU的两倍</p><p>D. ASIL-D通常要求使用双核锁步MCU</p><p><strong>正确答案：</strong> C</p><p><strong>详细解析：</strong></p><p>双核锁步的两个核执行<strong>相同的代码</strong>，因此计算能力与单核相同，而非两倍。第二个核是&quot;检查核&quot;，不承担额外计算任务。</p><ul><li><strong>选项A：</strong> 正确描述。两个核同步执行，比较器实时检查输出一致性。</li><li><strong>选项B：</strong> 正确描述。如果Core 0的ALU寄存器损坏导致计算错误，Core 1的计算结果会不同，比较器立即检测到。</li><li><strong>选项C：</strong> 错误。两个核做同样的事，计算能力不增加。如果需要额外算力，需要使用非锁步的第三个核（如Infineon Aurix的Core 2）。</li><li><strong>选项D：</strong> 正确描述。ASIL-D要求单点故障度量≥99%，普通单核MCU的CPU故障无法自检，必须使用锁步架构。</li></ul><hr><h3 id="第7题-看门狗选择" tabindex="-1">第7题：看门狗选择 <a class="header-anchor" href="#第7题-看门狗选择" aria-label="Permalink to &quot;第7题：看门狗选择&quot;">​</a></h3><p><strong>题目：</strong> 某ASIL-C的电机控制器，需要选择看门狗方案。以下方案最合适的是？</p><p>A. 独立看门狗(IWDG)，超时时间100ms</p><p>B. 窗口看门狗(WWDG)，窗口5~10ms</p><p>C. 问答看门狗(Q&amp;A WDG)，每次控制周期回答一个问题</p><p>D. 不需要看门狗，用软件自检代替</p><p><strong>正确答案：</strong> C</p><p><strong>详细解析：</strong></p><p>ASIL-C要求看门狗必须具备&quot;检测程序跑飞后仍在正确时间喂狗&quot;的能力。普通看门狗和窗口看门狗都无法做到这一点——程序跑飞后可能碰巧在正确时间喂狗。</p><ul><li><strong>选项A：</strong> 独立看门狗只能检测&quot;程序完全停止&quot;，无法检测&quot;程序跑飞但仍在喂狗&quot;的情况。ASIL-C不够。</li><li><strong>选项B：</strong> 窗口看门狗比独立看门狗更严格（必须在窗口内喂狗），但仍无法防止程序跑飞后碰巧在窗口内喂狗。</li><li><strong>选项C：</strong> 正确。问答看门狗要求软件根据问题计算答案，程序跑飞后无法正确计算，即使碰巧在正确时间回复，答案也是错的。这是ASIL-C/D推荐的方式。</li><li><strong>选项D：</strong> 软件自检无法检测&quot;软件本身跑飞&quot;的情况——这是看门狗存在的根本原因。</li></ul><hr><h3 id="第8题-spfm计算" tabindex="-1">第8题：SPFM计算 <a class="header-anchor" href="#第8题-spfm计算" aria-label="Permalink to &quot;第8题：SPFM计算&quot;">​</a></h3><p><strong>题目：</strong> 某系统有3个安全相关元器件，故障率和诊断覆盖率如下：</p><table tabindex="0"><thead><tr><th>元器件</th><th>λSP (FIT)</th><th>DC</th></tr></thead><tbody><tr><td>MCU内核</td><td>10</td><td>99%</td></tr><tr><td>电流采样</td><td>20</td><td>90%</td></tr><tr><td>PWM驱动</td><td>50</td><td>95%</td></tr></tbody></table><p>计算SPFM，并判断是否满足ASIL-B（≥97%）？</p><p>A. SPFM = 94.25%，不满足ASIL-B</p><p>B. SPFM = 97.0%，刚好满足ASIL-B</p><p>C. SPFM = 98.5%，满足ASIL-B</p><p>D. SPFM = 99.0%，满足ASIL-B</p><p><strong>正确答案：</strong> A</p><p><strong>详细解析：</strong></p><p>SPFM = 1 - Σ(λSPi·(1-DCi)) / Σ(λSPi)</p><p>计算过程：</p><ul><li>MCU内核：10 × (1-0.99) = 10 × 0.01 = 0.1 FIT</li><li>电流采样：20 × (1-0.90) = 20 × 0.10 = 2.0 FIT</li><li>PWM驱动：50 × (1-0.95) = 50 × 0.05 = 2.5 FIT</li><li>Σ(λSPi·(1-DCi)) = 0.1 + 2.0 + 2.5 = 4.6 FIT</li><li>Σ(λSPi) = 10 + 20 + 50 = 80 FIT</li><li>SPFM = 1 - 4.6/80 = 1 - 0.0575 = <strong>94.25%</strong></li></ul><p>ASIL-B要求SPFM ≥ 97%，94.25% &lt; 97%，<strong>不满足</strong>。</p><p><strong>改进方向</strong>：电流采样的DC=90%是主要瓶颈（贡献2.0/4.6=43.5%的残余故障率），需要提高其诊断覆盖率至97%以上。</p><hr><h2 id="第二部分-hara分析题" tabindex="-1">第二部分：HARA分析题 <a class="header-anchor" href="#第二部分-hara分析题" aria-label="Permalink to &quot;第二部分：HARA分析题&quot;">​</a></h2><h3 id="第9题-电动滑板车电机控制器hara" tabindex="-1">第9题：电动滑板车电机控制器HARA <a class="header-anchor" href="#第9题-电动滑板车电机控制器hara" aria-label="Permalink to &quot;第9题：电动滑板车电机控制器HARA&quot;">​</a></h3><p><strong>题目：</strong> 某电动滑板车（最高速度25km/h），电机控制器可能发生&quot;电机突然全速运转&quot;的危害事件。请完成HARA分析，确定ASIL等级。</p><p><strong>要求</strong>：</p><ol><li>评估严重度(S)、暴露率(E)、可控性(C)，给出理由</li><li>查ASIL等级矩阵确定ASIL</li><li>提出至少2条安全措施</li></ol><p><strong>参考答案</strong>：</p><p><strong>1. HARA评估</strong>：</p><table tabindex="0"><thead><tr><th>维度</th><th>等级</th><th>理由</th></tr></thead><tbody><tr><td>严重度(S)</td><td>S2(重伤)</td><td>25km/h突然加速可导致骑行者摔倒重伤，但通常不致命</td></tr><tr><td>暴露率(E)</td><td>E4(频繁)</td><td>骑行时电机始终在工作，暴露率极高</td></tr><tr><td>可控性(C)</td><td>C2(很难控)</td><td>滑板车无座椅，突然加速骑行者可能被甩出，但可尝试跳车</td></tr></tbody></table><p><strong>2. ASIL等级</strong>：S2×E4×C2 → 查表得 <strong>ASIL-C</strong></p><p><strong>3. 安全措施</strong>：</p><ul><li>双路霍尔传感器交叉验证（检测非预期加速）</li><li>软件速度变化率限制（加速度&gt;阈值→限制输出）</li><li>看门狗监控MCU运行</li><li>安全状态：主动制动→减速→高阻态</li></ul><hr><h3 id="第10题-工业机器人关节驱动hara" tabindex="-1">第10题：工业机器人关节驱动HARA <a class="header-anchor" href="#第10题-工业机器人关节驱动hara" aria-label="Permalink to &quot;第10题：工业机器人关节驱动HARA&quot;">​</a></h3><p><strong>题目：</strong> 某工业机器人关节驱动电机（最大转速3000rpm，最大转矩50Nm），可能发生&quot;电机突然输出最大转矩&quot;的危害事件。请完成HARA分析。</p><p><strong>要求</strong>：</p><ol><li>评估严重度(S)、暴露率(E)、可控性(C)</li><li>确定ASIL等级</li><li>分析安全状态选择（高阻态 vs 短路制动 vs 主动制动）</li></ol><p><strong>参考答案</strong>：</p><p><strong>1. HARA评估</strong>：</p><table tabindex="0"><thead><tr><th>维度</th><th>等级</th><th>理由</th></tr></thead><tbody><tr><td>严重度(S)</td><td>S3(致命)</td><td>50Nm突然转矩可导致机械臂猛烈运动，碾压附近人员</td></tr><tr><td>暴露率(E)</td><td>E3(经常)</td><td>工业机器人长时间运行，人员可能在附近维护</td></tr><tr><td>可控性(C)</td><td>C3(不可控)</td><td>人员无法对抗50Nm的机械臂运动</td></tr></tbody></table><p><strong>2. ASIL等级</strong>：S3×E3×C3 → 查表得 <strong>ASIL-D</strong></p><p><strong>3. 安全状态分析</strong>：</p><table tabindex="0"><thead><tr><th>安全状态</th><th>适用性</th><th>分析</th></tr></thead><tbody><tr><td>高阻态</td><td>❌ 不适用</td><td>电机自由减速，但机械臂可能在重力作用下继续运动，危险</td></tr><tr><td>短路制动</td><td>⚠️ 部分适用</td><td>快速制动，但制动转矩不可控，可能导致机械冲击</td></tr><tr><td>主动制动</td><td>✅ 最优</td><td>施加可控的制动转矩，平滑减速到安全位置后保持</td></tr></tbody></table><p><strong>推荐安全状态</strong>：主动制动→减速至安全位置→位置保持（伺服锁定）→高阻态</p><hr><h2 id="第三部分-fmea表格填写题" tabindex="-1">第三部分：FMEA表格填写题 <a class="header-anchor" href="#第三部分-fmea表格填写题" aria-label="Permalink to &quot;第三部分：FMEA表格填写题&quot;">​</a></h2><h3 id="第11题-位置传感器fmea" tabindex="-1">第11题：位置传感器FMEA <a class="header-anchor" href="#第11题-位置传感器fmea" aria-label="Permalink to &quot;第11题：位置传感器FMEA&quot;">​</a></h3><p><strong>题目：</strong> 对永磁同步电机的编码器（增量式）进行FMEA分析，列出至少5种失效模式。</p><p><strong>参考答案</strong>：</p><table tabindex="0"><thead><tr><th>序号</th><th>元器件</th><th>失效模式</th><th>失效影响</th><th>检测方法</th><th>DC估计</th></tr></thead><tbody><tr><td>1</td><td>编码器</td><td>ABZ信号全部丢失</td><td>无法获取位置→电机失控</td><td>信号超时检测</td><td>99%</td></tr><tr><td>2</td><td>编码器</td><td>A相信号丢失</td><td>速度计算错误→转速波动</td><td>BZ信号计数不一致</td><td>90%</td></tr><tr><td>3</td><td>编码器</td><td>Z信号丢失</td><td>无法确定绝对位置→启动定位失败</td><td>上电自检Z信号</td><td>95%</td></tr><tr><td>4</td><td>编码器</td><td>信号噪声干扰</td><td>位置抖动→转矩脉动增大</td><td>信号变化率检查</td><td>80%</td></tr><tr><td>5</td><td>编码器</td><td>机械安装松动</td><td>角度偏移→效率下降</td><td>观测器角度与编码器角度偏差检查</td><td>70%</td></tr><tr><td>6</td><td>编码器</td><td>温度漂移</td><td>零点偏移→低速爬行</td><td>上电零点校验</td><td>60%</td></tr></tbody></table><p><strong>关键洞察</strong>：编码器信号丢失的DC很高（99%），但信号噪声和安装松动的DC较低。对于ASIL-C/D应用，需要增加冗余位置传感器（如旋变+霍尔）来提高整体DC。</p><hr><h3 id="第12题-电源系统fmea" tabindex="-1">第12题：电源系统FMEA <a class="header-anchor" href="#第12题-电源系统fmea" aria-label="Permalink to &quot;第12题：电源系统FMEA&quot;">​</a></h3><p><strong>题目：</strong> 对电机控制器的电源系统（开关电源+LDO）进行FMEA分析，列出至少5种失效模式。</p><p><strong>参考答案</strong>：</p><table tabindex="0"><thead><tr><th>序号</th><th>元器件</th><th>失效模式</th><th>失效影响</th><th>检测方法</th><th>DC估计</th></tr></thead><tbody><tr><td>1</td><td>开关电源</td><td>输出过压</td><td>MCU和驱动IC过压损坏</td><td>ADC采样+过压比较器</td><td>99%</td></tr><tr><td>2</td><td>开关电源</td><td>输出欠压</td><td>MCU复位或运行异常</td><td>ADC采样+欠压检测(BOR)</td><td>99%</td></tr><tr><td>3</td><td>LDO</td><td>输出短路</td><td>MCU供电丢失→系统停机</td><td>ADC采样+电源监测IC</td><td>95%</td></tr><tr><td>4</td><td>LDO</td><td>输出电压漂移</td><td>ADC基准偏移→采样不准</td><td>基准电压自检</td><td>70%</td></tr><tr><td>5</td><td>母线电容</td><td>容量衰减</td><td>纹波增大→过流误触发</td><td>母线纹波监测</td><td>50%</td></tr><tr><td>6</td><td>电源IC</td><td>使能脚悬空</td><td>电源无法启动</td><td>上电自检</td><td>99%</td></tr></tbody></table><p><strong>关键洞察</strong>：LDO输出电压漂移和母线电容衰减的DC较低，是潜伏故障的常见来源。对于ASIL-B/C，需要定期执行上电诊断（Power-On Self Test）来检测这些潜伏故障。</p><hr><h2 id="第四部分-安全状态设计题" tabindex="-1">第四部分：安全状态设计题 <a class="header-anchor" href="#第四部分-安全状态设计题" aria-label="Permalink to &quot;第四部分：安全状态设计题&quot;">​</a></h2><h3 id="第13题-电动工具电机控制器安全状态设计" tabindex="-1">第13题：电动工具电机控制器安全状态设计 <a class="header-anchor" href="#第13题-电动工具电机控制器安全状态设计" aria-label="Permalink to &quot;第13题：电动工具电机控制器安全状态设计&quot;">​</a></h3><p><strong>题目：</strong> 某电动工具（手持式电钻，最高转速1500rpm，最大转矩10Nm）的电机控制器需要满足IEC 60335-1 Annex R的安全要求。请设计完整的安全状态序列，包括：</p><ol><li>需要考虑的危害事件（至少3个）</li><li>每个危害事件的安全状态</li><li>从故障检测到安全状态进入的完整时序</li><li>硬件和软件的分工</li></ol><p><strong>参考答案</strong>：</p><p><strong>1. 危害事件与安全状态</strong>：</p><table tabindex="0"><thead><tr><th>危害事件</th><th>ASIL/SIL等级</th><th>安全状态</th><th>FTTI</th></tr></thead><tbody><tr><td>电机非预期运转（松开扳机不停）</td><td>IEC 60335 Class B</td><td>高阻态（关PWM）</td><td>100ms</td></tr><tr><td>过流（堵转导致电流过大）</td><td>IEC 60335 Class B</td><td>短路制动→高阻态</td><td>50μs</td></tr><tr><td>MCU程序跑飞</td><td>IEC 60335 Class B</td><td>看门狗复位→进入安全状态</td><td>10ms</td></tr></tbody></table><p><strong>2. 非预期运转安全状态时序</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>T=0ms:    用户松开扳机，但电机未停止</span></span>
<span class="line"><span>          → 软件检测到扳机信号=0但电机仍在运转</span></span>
<span class="line"><span>T=5ms:    软件设置故障标志</span></span>
<span class="line"><span>          → 状态机转入FAULT</span></span>
<span class="line"><span>T=5ms:    FAULT进入函数执行</span></span>
<span class="line"><span>          → 关闭PWM输出（高阻态）</span></span>
<span class="line"><span>          → 电机自由减速</span></span>
<span class="line"><span>T=5ms:    上报故障码</span></span>
<span class="line"><span>          → LED闪烁报警</span></span>
<span class="line"><span>T=1~3s:   电机停止</span></span>
<span class="line"><span>          → 等待故障复位（重新上电）</span></span></code></pre></div><p><strong>3. 过流保护安全状态时序</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>T=0μs:    电流超过硬件阈值</span></span>
<span class="line"><span>          → 硬件比较器触发BRK引脚</span></span>
<span class="line"><span>          → PWM立即封锁（μs级）</span></span>
<span class="line"><span>T=0.1ms:  软件过流检测确认</span></span>
<span class="line"><span>          → 设置故障标志</span></span>
<span class="line"><span>          → 状态机转入FAULT</span></span>
<span class="line"><span>T=0.1ms:  FAULT进入函数执行</span></span>
<span class="line"><span>          → 下桥臂全导通（短路制动）</span></span>
<span class="line"><span>          → 记录故障码</span></span>
<span class="line"><span>T=0.5ms:  电机快速减速</span></span>
<span class="line"><span>T=0.5~2s: 电机停止</span></span>
<span class="line"><span>          → 切换到高阻态</span></span></code></pre></div><p><strong>4. 硬件与软件分工</strong>：</p><table tabindex="0"><thead><tr><th>功能</th><th>硬件实现</th><th>软件实现</th><th>理由</th></tr></thead><tbody><tr><td>过流快速保护</td><td>✅ 比较器+BRK引脚</td><td>❌ 响应不够快</td><td>FTTI=50μs，软件无法保证</td></tr><tr><td>过流延时确认</td><td>❌ 灵活性差</td><td>✅ 可编程阈值+延时</td><td>避免瞬态误触发</td></tr><tr><td>非预期运转检测</td><td>❌ 逻辑复杂</td><td>✅ 扳机信号+转速判断</td><td>FTTI=100ms，软件可实现</td></tr><tr><td>看门狗</td><td>✅ 硬件看门狗</td><td>❌ 软件无法自检</td><td>程序跑飞时软件不可信</td></tr><tr><td>安全状态执行</td><td>✅ PWM封锁（硬件BRK）</td><td>✅ 短路制动（软件控制）</td><td>硬件保证最快响应，软件提供精细控制</td></tr><tr><td>故障记录</td><td>❌ 无存储能力</td><td>✅ 写入Flash/EEPROM</td><td>软件负责记录和上报</td></tr></tbody></table><hr><h2 id="评分标准" tabindex="-1">评分标准 <a class="header-anchor" href="#评分标准" aria-label="Permalink to &quot;评分标准&quot;">​</a></h2><h3 id="总分计算" tabindex="-1">总分计算 <a class="header-anchor" href="#总分计算" aria-label="Permalink to &quot;总分计算&quot;">​</a></h3><table tabindex="0"><thead><tr><th>题型</th><th>题号</th><th>分值</th><th>小计</th></tr></thead><tbody><tr><td>概念理解</td><td>第1~8题</td><td>每题5分</td><td>40分</td></tr><tr><td>HARA分析</td><td>第9~10题</td><td>每题15分</td><td>30分</td></tr><tr><td>FMEA表格</td><td>第11~12题</td><td>每题10分</td><td>20分</td></tr><tr><td>安全状态设计</td><td>第13题</td><td>10分</td><td>10分</td></tr><tr><td><strong>合计</strong></td><td>-</td><td>-</td><td><strong>100分</strong></td></tr></tbody></table><h3 id="评分细则" tabindex="-1">评分细则 <a class="header-anchor" href="#评分细则" aria-label="Permalink to &quot;评分细则&quot;">​</a></h3><p><strong>概念理解题（第1~8题）</strong>：</p><ul><li>选对得5分，选错得0分</li><li>无半对分数</li></ul><p><strong>HARA分析题（第9~10题）</strong>：</p><ul><li>S/E/C评估合理且有理由：每项3分，共9分</li><li>ASIL等级正确：3分</li><li>安全措施合理：3分（每条1.5分）</li></ul><p><strong>FMEA表格题（第11~12题）</strong>：</p><ul><li>每行（失效模式+影响+检测+DC）：2分</li><li>至少5行，共10分</li><li>DC估计合理即可，不要求精确</li></ul><p><strong>安全状态设计题（第13题）</strong>：</p><ul><li>危害事件识别：3分</li><li>安全状态设计：3分</li><li>时序设计：2分</li><li>硬件/软件分工：2分</li></ul><h3 id="等级评定" tabindex="-1">等级评定 <a class="header-anchor" href="#等级评定" aria-label="Permalink to &quot;等级评定&quot;">​</a></h3><table tabindex="0"><thead><tr><th>总分</th><th>等级</th><th>评价</th></tr></thead><tbody><tr><td>90~100</td><td>A</td><td>深刻理解功能安全方法论，能独立完成HARA/FMEA分析和安全状态设计</td></tr><tr><td>75~89</td><td>B</td><td>掌握功能安全核心概念，HARA/FMEA分析能力需进一步实践</td></tr><tr><td>60~74</td><td>C</td><td>了解功能安全基本概念，但定量分析能力不足，需加强SPFM/LFM计算练习</td></tr><tr><td>&lt;60</td><td>D</td><td>功能安全知识体系尚未建立，建议从ISO 26262 Part 1-3开始系统学习</td></tr></tbody></table><hr><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><h3 id="按等级的改进方向" tabindex="-1">按等级的改进方向 <a class="header-anchor" href="#按等级的改进方向" aria-label="Permalink to &quot;按等级的改进方向&quot;">​</a></h3><p><strong>A级（90~100）</strong>：</p><ul><li>深入学习ISO 26262 Part 5（硬件安全）和Part 6（软件安全）</li><li>尝试完成一个完整的FMEA分析项目</li><li>学习故障注入测试方法</li></ul><p><strong>B级（75~89）</strong>：</p><ul><li>加强HARA分析的实践，多做不同场景的练习</li><li>重点理解SPFM/LFM/PMHF的计算方法和改进策略</li><li>学习FTA（故障树分析）方法，与FMEA互补</li></ul><p><strong>C级（60~74）</strong>：</p><ul><li>重新学习本模块第4节（技术原理），重点关注4.2~4.6节</li><li>理解ASIL等级矩阵的使用方法</li><li>练习SPFM计算，至少完成3组不同数据的计算</li></ul><p><strong>D级（&lt;60）</strong>：</p><ul><li>建议先学习ISO 26262 Part 1（概述）和Part 3（概念阶段）</li><li>理解功能安全的基本术语：危害、风险、安全目标、安全状态</li><li>从简单的过流保护案例开始，逐步理解功能安全的思维方式</li></ul><h3 id="推荐学习路径" tabindex="-1">推荐学习路径 <a class="header-anchor" href="#推荐学习路径" aria-label="Permalink to &quot;推荐学习路径&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第1步：理解概念（本模块第1~3节）</span></span>
<span class="line"><span>  → 掌握ASIL等级、安全状态、FTTI等核心概念</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第2步：学习HARA方法（本模块第4.2节）</span></span>
<span class="line"><span>  → 完成2~3个不同场景的HARA分析练习</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第3步：学习FMEA方法（本模块第4.5节）</span></span>
<span class="line"><span>  → 对电流采样、位置传感器、电源系统分别做FMEA</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第4步：学习硬件度量计算（本模块第4.6节）</span></span>
<span class="line"><span>  → 完成SPFM/LFM/PMHF的计算练习</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第5步：学习安全状态设计（本模块第4.4节）</span></span>
<span class="line"><span>  → 设计不同场景的安全状态序列</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第6步：综合实践</span></span>
<span class="line"><span>  → 完成一个完整的电机控制器安全分析案例</span></span></code></pre></div><h3 id="扩展阅读" tabindex="-1">扩展阅读 <a class="header-anchor" href="#扩展阅读" aria-label="Permalink to &quot;扩展阅读&quot;">​</a></h3><ol><li>ISO 26262-3:2018 - 概念阶段（HARA方法详解）</li><li>ISO 26262-5:2018 - 硬件开发（SPFM/LFM/PMHF计算方法）</li><li>ISO 26262-6:2018 - 软件开发（MISRA C、看门狗、内存保护）</li><li>IEC 61508-2:2010 - 安全要求规范</li><li><a href="./SYS-01-Design-Patterns.html">SYS-01 设计模式</a> - 状态机与故障处理架构</li><li><a href="./../../algorithm/ALG-13-Protection-Optimization.html">ALG-13 保护优化</a> - 过流/过压/过温保护设计</li></ol><hr><blockquote><p><strong>关联模块：</strong> <a href="./SYS-05-Functional-Safety.html">SYS-05 功能安全：电控系统的生命线</a></p></blockquote>`,179)])])}const c=a(r,[["render",l]]);export{u as __pageData,c as default};
